import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function App() {
  const [data, setData] = React.useState(appsmith.model.data || []);
  const [selected, setSelected] = React.useState(null);
  const [ascending, setAscending] = React.useState(true);

  React.useEffect(() => {
    let last = JSON.stringify(appsmith.model.data || []);
    const sync = () => {
      const cur = JSON.stringify(appsmith.model.data || []);
      if (cur !== last) { last = cur; setData(appsmith.model.data || []); }
    };
    if (appsmith.onModelChange) { try { appsmith.onModelChange(sync); } catch (e) {} }
    const id = setInterval(sync, 800);
    return () => clearInterval(id);
  }, []);

  const sortedOptions = React.useMemo(() => {
    return [...data].sort((a,b)=> ascending ? a.label.localeCompare(b.label) : b.label.localeCompare(a.label));
  }, [data, ascending]);

  const toggleValue = (value) => {
    let newValue = selected === value ? null : value;
    setSelected(newValue);
    appsmith.updateModel({ selectedValue: newValue });
    appsmith.triggerEvent("onSelectChange");
  };

  const toggleSort = () => setAscending(!ascending);

  return (
    <div className="app">
      <div className="header">
        <div>Locations</div>
        <div className="sortIcon" onClick={toggleSort}>{ascending ? "▲" : "▼"}</div>
      </div>
      <div className="list">
        {sortedOptions.map((opt,i)=>(
          <div
            key={i}
            className={"row " + (selected===opt.value ? "selected":"")}
            onClick={()=>toggleValue(opt.value)}
          >
            {opt.label}
          </div>
        ))}
      </div>
    </div>
  );
}

appsmith.onReady(()=>{
  ReactDOM.render(<App />, document.getElementById("root"));
});
